+    fn run(mut self) -> W {
+        let is_binary = self.is_binary();
+        let mut it = self.grep.iter(self.buf).peekable();
+        if is_binary && it.peek().is_some() {
+            self.printer.binary_matched(self.path);
+            return self.printer.into_inner();
+        }
